import csv

import click


def fetch_users(limit):
    return [(i, f"user{i}") for i in range(limit)]


@click.command()
@click.argument("output", type=click.Path(dir_okay=False))
@click.option("--limit", default=100, show_default=True, help="Rows to export.")
@click.option("--verbose", "-v", is_flag=True, help="Print a summary.")
def main(output, limit, verbose):
    rows = fetch_users(limit)
    with open(output, "w", newline="") as f:
        csv.writer(f).writerows(rows)
    if verbose:
        click.echo(f"wrote {len(rows)} rows to {output}")


if __name__ == "__main__":
    main()
